package workshop.vfx.paper.m8;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static workshop.vfx.paper.m8.K1Fixture.*;
import java.util.*;
import workshop.vfx.delivery.*;
import workshop.vfx.paper.core.*;
import workshop.vfx.scene.*;

class K1BudgetAndSchedulingTest {
    @Test void ringAndAuraUseExactlyOneGlobalPlanAndOneTask(){var f=new K1Fixture();f.ring(A);f.balanced();f.run();assertEquals(1,f.schedules);assertEquals(1,f.plans);assertEquals(2,f.requests.size());assertEquals(75,f.plan.reservedGeneratedPoints());assertEquals(75,f.driver.lastReport().succeededCalls());f.driver.stop(A);f.step();assertEquals(2,f.plans);assertEquals(27,f.sends.size());assertEquals(1,f.schedules);}
    @Test void capacityIsSharedInBothStartOrdersAndReplacementAtCap(){for(boolean ringFirst:List.of(false,true)){var f=new K1Fixture(Map.of("maxActiveEffects",2),Map.of());if(ringFirst){f.ring(A);f.balanced();}else{f.balanced();f.ring(A);}assertThrows(IllegalArgumentException.class,()->f.auras.start(B,QualityTier.SIMPLE,f.tick));assertThrows(IllegalArgumentException.class,()->f.ring(B));f.start(QualityTier.HEAVY);f.ring(A);assertEquals(1,f.registry.activeCount());assertEquals(1,f.driver.activeCount());f.auras.stop(A);f.auras.start(B,QualityTier.SIMPLE,f.tick);assertEquals(1,f.schedules);}}
    @Test void perPlayerCapAndReplacementRespectK0Registry(){var f=new K1Fixture(Map.of(),Map.of("maxEffectsPerPlayer",1));f.balanced();assertThrows(IllegalArgumentException.class,()->f.registry.start(A,EffectKind.TRAIL,(id,b)->{throw new AssertionError("must not build a deferred effect");}));f.start(QualityTier.HEAVY);assertEquals(1,f.registry.countOwner(A));}
    @Test void emissionAndViewerBudgetsAreAlignedAndFullyAccounted(){var f=new K1Fixture(Map.of("maxCallsPerTick",20,"maxCallsPerViewerPerTick",10),Map.of());f.canView.add(B);f.start(QualityTier.HEAVY);for(int i=0;i<20;i++){f.run();assertTrue(f.plan.placements()<=20);assertTrue(f.sendsTo(A)<=10);assertTrue(f.sendsTo(B)<=10);assertFalse(f.driver.lastReport().skippedPoints().containsKey(SkipReason.EMISSION_LIMIT));f.account();f.tick++;}}
    @Test void zeroGenerationBudgetProducesNoCallsAndNoExtraTasks(){var f=new K1Fixture(Map.of("generatedPointBudget",0),Map.of());f.balanced();f.run();assertEquals(0,f.plan.reservedGeneratedPoints());assertEquals(0,f.sends.size());assertTrue(f.registry.active());assertEquals(1,f.schedules);}
    @Test void strictSimpleCeilingNeverPromotesWhenBudgetAllowsHeavy(){var f=new K1Fixture();f.start(QualityTier.SIMPLE);f.run();assertEquals(12,f.plan.sourcePoints());assertEquals(12,f.sends.size());assertTrue(f.sends.stream().allMatch(s->s.style().equals(DemoStyleCatalog.END_ROD)));}
    @Test void persistentCyanFailureDisablesOnlyThatStyleAndAccountingRemainsExact(){var f=new K1Fixture();f.balanced();f.failCyan=true;f.run();assertEquals(3,f.driver.lastReport().failedCalls());assertEquals(18,f.driver.lastReport().succeededCalls());assertTrue(f.health.isDisabled(M8StyleCatalog.CYAN_HALO));assertFalse(f.health.isDisabled(DemoStyleCatalog.END_ROD));f.account();f.step();assertEquals(0,f.driver.lastReport().failedCalls());assertEquals(18,f.sends.size());assertEquals(9,f.plan.unsupportedPoints());f.account();}
    @Test void unresolvedCyanStyleIsRemovedFromPlanningWithoutFallbackPayload(){var f=new K1Fixture();f.balanced();for(int i=0;i<3;i++)f.health.recordFailure(M8StyleCatalog.CYAN_HALO);f.run();assertEquals(18,f.sends.size());assertEquals(9,f.plan.unsupportedPoints());assertTrue(f.sends.stream().allMatch(s->s.style().equals(DemoStyleCatalog.END_ROD)));}
    @Test void sustainedAllTierRunsKeepExactCountsAndNoSchedulingGrowth(){for(var tier:QualityTier.values()){var f=new K1Fixture(Map.of(),Map.of("auraLifetimeTicks",12000));f.start(tier);long generated=0,placements=0,calls=0;for(int i=0;i<1800;i++){f.run();if(i>=600){generated+=f.plan.sourcePoints();placements+=f.plan.placements();calls+=f.driver.lastReport().succeededCalls();assertEquals(0,f.driver.lastReport().failedCalls());}f.tick++;}int n=tier==QualityTier.SIMPLE?12:tier==QualityTier.BALANCED?27:36;assertEquals(1200L*n,generated);assertEquals(generated,placements);assertEquals(placements,calls);assertEquals(1,f.schedules);assertEquals(0,f.cancels);f.driver.close();assertEquals(1,f.cancels);}}
    @Test void longSoakStartStopWorldChangesRemainBoundedAndClear(){var f=new K1Fixture(Map.of(),Map.of("auraLifetimeTicks",12000));for(int i=0;i<72000;i++){if(i%1000==0)f.start(QualityTier.HEAVY);if(i%499==0)f.worlds.put(A,f.worlds.get(A).equals(W)?W2:W);f.run();assertTrue(f.registry.activeCount()<=1);assertEquals(1,f.schedules);f.tick++;}f.driver.close();assertEquals(0,f.registry.activeCount());assertEquals(1,f.cancels);}
}
